const normalizeAttrKey = (name) => toLower(name).replace(/colour/g, "color").replace(/[^a-z0-9\s_-]/g, "").replace(/[\s-]+/g, "_").replace(/_+/g, "_").replace(/^_+|_+$/g, "");
