  const subgroupSlug = firstDefined(p.subgroupSlug, p.subgroup_slug, p.subcategorySlug, p.subcategory_slug, q.subgroupSlug, q.subgroup_slug, q.subcategory_slug);
  const groupSlug = firstDefined(p.groupSlug, p.group_slug, q.groupSlug, q.group_slug, q.parent_slug);
