  const subgroupId = toIntStrict(firstDefined(p.subgroupId, p.subgroup_id, q.subgroupId, q.subgroup_id));
  const groupId = toIntStrict(firstDefined(p.groupId, p.group_id, q.groupId, q.group_id, q.parent_category_id));
