function normalizeAttributeGroupHeading(existingHeading, incomingHeading) { const a = sanitize(existingHeading || ""); const b = sanitize(incomingHeading || ""); if (!a) return b; if (!b) return a; if (a.toLowerCase() === b.toLowerCase()) return a; return a.length >= b.length ? a : b; }
function mergeAttributeGroups(cards) { const groups = new Map(); for (const card of cards || []) { const attrs = Array.isArray(card.attributes) ? card.attributes : []; for (const attr of attrs) { const heading = sanitize(attr.attribute_name || attr.heading || ""); const key = normalizeAttrKey(attr.attribute_slug || attr.key || heading); const value = sanitize(attr.attribute_value || attr.value || ""); if (!heading || !key || !value) continue; if (!groups.has(key)) groups.set(key, { heading, key, values: new Map() }); const entry = groups.get(key); entry.heading = normalizeAttributeGroupHeading(entry.heading, heading); const valueKey = toLower(value); if (!entry.values.has(valueKey)) entry.values.set(valueKey, { value, count: 0 }); entry.values.get(valueKey).count += 1; } } return Array.from(groups.values()).map((g) => ({ heading: g.heading, key: g.key, values: Array.from(g.values.values()).sort((a, b) => String(a.value || "").localeCompare(String(b.value || ""))) })).sort((a, b) => String(a.heading || "").localeCompare(String(b.heading || ""))); }

async function fetchVariantRowsByWhere(whereSql, params = []) { const q = `SELECT v.id, v.product_id, v.name AS variant_name, v.sku, v.price, v.sale_price, v.stock, v.cost_price, v.vat_rate, v.vat_included, v.discount_type, v.discount_value, v.low_stock_threshold, v.track_inventory, v.allow_backorders, v.barcode, v.barcode_type, v.weight, v.weight_unit, v.length, v.width, v.height, v.dimension_unit, v.shipping_class, v.is_active AS variant_is_active, v.is_default, v.sort_order, v.display_name, v.created_at AS variant_created_at, v.updated_at AS variant_updated_at, p.product_id AS master_product_code, p.name AS product_name, p.slug AS product_slug, p.product_type, p.brand, p.mpn, p.bullets, p.description, p.short_description, p.visibility, p.meta_keywords, p.meta_title, p.meta_description, p.main_image, p.product_videos, p.display_locations, p.display_timing, p.parent_category_id, p.category_id, p.created_at AS product_created_at, p.updated_at AS product_updated_at, pc.name AS parent_category_name, pc.slug AS parent_category_slug, c.name AS category_name, c.slug AS category_slug, c.parent_id AS category_parent_id, COALESCE(vm.filename, p.main_image) AS image FROM product_variants v JOIN products p ON p.id = v.product_id LEFT JOIN parent_categories pc ON pc.id = p.parent_category_id LEFT JOIN categories c ON c.id = p.category_id LEFT JOIN LATERAL ( SELECT filename FROM variant_media vm WHERE vm.variant_id = v.id ORDER BY vm.id DESC NULLS LAST, vm.created_at DESC NULLS LAST LIMIT 1 ) vm ON TRUE ${whereSql} ORDER BY GREATEST(COALESCE(v.created_at, NOW()), COALESCE(v.updated_at, NOW())) DESC, v.sort_order ASC NULLS LAST, v.id DESC`; const res = await pool.query(q, params); return res.rows || []; }
