  const { finalPrice, discountValue, vatValue } = calculateFinalPrice(basePrice, discountPercent, vatRate);
  const masterName = sanitize(variantRow.product_name || "");
  const variantName = sanitize(variantRow.variant_name || variantRow.display_name || "");
  const displayName = variantName ? `${masterName} ${variantName}`.trim() : masterName || variantName;
  const image = sanitize(variantRow.image || variantRow.main_image || "");
